def levenshtein_shortcircuit_dist(s, t, max_dist=3):
    #as seen from https://www.python-course.eu/levenshtein_distance.php
    rows = len(s)+1
    cols = len(t)+1

    # 边界处理：任一为空串时，编辑距离即为另一串长度，
    # 避免主循环不执行导致 row/col 未定义（NameError）。
    if rows == 1 or cols == 1:
        d = rows - 1 + cols - 1
        if d < max_dist:
            return True, d
        return False, 100000

    if abs(rows-cols)> max_dist:
        return False, 10000

    dist = [[0 for x in range(cols)] for x in range(rows)]
    # source prefixes can be transformed into empty strings 
    # by deletions:
    for i in range(1, rows):
        dist[i][0] = i
    # target prefixes can be created from an empty source string
    # by inserting the characters
    for i in range(1, cols):
        dist[0][i] = i

    for col in range(1, cols):
        max_num = 1000000
        for row in range(1, rows):
            if s[row-1] == t[col-1]:
                cost = 0
            else:
                cost = 1
            dist[row][col] = min(dist[row-1][col] + 1,      # deletion
                                 dist[row][col-1] + 1,      # insertion
                                 dist[row-1][col-1] + cost) # substitution
            if dist[row][col] < max_num:
                max_num = dist[row][col]
        if max_num >= max_dist:
            return False, 100000
    #print dist[row][col]
    if dist[row][col] < max_dist:
        return True, dist[row][col]
    return False, 100000
    #return dist[row][col]

